use vstd::prelude::*;

verus! {
    //
    // solve:
    //   Given two sorted arrays `a` and `b` of signed 8‐bit ints,
    //   of lengths n_a and n_b respectively (both ≥ 1),
    //   and two 1‐based indices k ∈ [1, n_a], m ∈ [1, n_b],
    //   decide whether a[k] < b[n_b - m + 1].
    //   Return "YES" if so, otherwise "NO".
    //
    fn solve(
        n_a: i8,
        n_b: i8,
        k: i8,
        m: i8,
        a: Vec<i8>,
        b: Vec<i8>,
    ) -> &'static str
        requires
            // sizes positive
            0 < n_a,
            0 < n_b,
            // index bounds
            1 <= k && k <= n_a,
            1 <= m && m <= n_b,
            // lengths match declared sizes
            a.len() == n_a as nat,
            b.len() == n_b as nat,
            // a is sorted non‐decreasing
            forall |i: nat|
                i + 1 < a.len() ==>
                a[i] <= a[i + 1],
            // b is sorted non‐decreasing
            forall |i: nat|
                i + 1 < b.len() ==>
                b[i] <= b[i + 1],
        ensures
            // we return "YES" exactly when a[k-1] < b[n_b-m]
            (result == "YES") ==
            (a[(k - 1) as usize] < b[(b.len() - (m as nat)) as usize]),
    {
        // compute the two elements to compare
        let ai = a[(k - 1) as usize];
        let bj = b[(b.len() - (m as nat)) as usize];
        if ai < bj {
            "YES"
        } else {
            "NO"
        }
    }
}

