    let a = vec![1i8, 3, 5];
    let b = vec![2i8, 4, 6];
    // n_a = 3, n_b = 3, k = 2 (a[2] = 3), m = 1 (b[3] = 6)
    assert!(solve(3, 3, 2, 1, a.clone(), b.clone()) == "YES");
    // m = 2 (b[2] = 4)
    assert!(solve(3, 3, 2, 2, a, b) == "NO");
